import assert from 'node:assert/strict';
import { test } from 'node:test';
import { z } from 'zod';
import { toJsonSchema } from '@coderax/contracts';

/**
 * The OpenAPI document is generated by this walker, so every construct it
 * claims to support needs a test. The walker reads zod 4's `_zod.def` shape; a
 * zod upgrade that changes those internals must fail here rather than silently
 * publishing a schema the server does not enforce.
 */

test('scalar types map to their JSON Schema equivalents', () => {
  assert.deepEqual(toJsonSchema(z.string()), { type: 'string' });
  assert.deepEqual(toJsonSchema(z.number()), { type: 'number' });
  assert.deepEqual(toJsonSchema(z.boolean()), { type: 'boolean' });
  assert.deepEqual(toJsonSchema(z.null()), { type: 'null' });
  assert.deepEqual(toJsonSchema(z.any()), {});
  assert.deepEqual(toJsonSchema(z.unknown()), {});
});

test('string length and format checks are published', () => {
  assert.deepEqual(toJsonSchema(z.string().min(2).max(5)), {
    type: 'string',
    minLength: 2,
    maxLength: 5,
  });
  assert.deepEqual(toJsonSchema(z.string().datetime()), {
    type: 'string',
    format: 'date-time',
  });
  assert.deepEqual(toJsonSchema(z.string().url()), { type: 'string', format: 'uri' });
  assert.deepEqual(toJsonSchema(z.string().email()), { type: 'string', format: 'email' });
});

test('number bounds, integer and sign checks are published', () => {
  assert.deepEqual(toJsonSchema(z.number().int()), { type: 'integer' });
  assert.deepEqual(toJsonSchema(z.number().min(1).max(10)), {
    type: 'number',
    minimum: 1,
    maximum: 10,
  });
  assert.deepEqual(toJsonSchema(z.number().gt(0)), {
    type: 'number',
    exclusiveMinimum: 0,
  });
  assert.deepEqual(toJsonSchema(z.number().positive()), {
    type: 'number',
    exclusiveMinimum: 0,
  });
  assert.deepEqual(toJsonSchema(z.number().negative()), {
    type: 'number',
    exclusiveMaximum: 0,
  });
});

test('literals and enums publish a closed value set', () => {
  assert.deepEqual(toJsonSchema(z.literal('only')), { const: 'only' });
  assert.deepEqual(toJsonSchema(z.literal(7)), { const: 7 });
  assert.deepEqual(toJsonSchema(z.enum(['a', 'b'])), {
    type: 'string',
    enum: ['a', 'b'],
  });
});

test('arrays publish their item schema and their length bounds', () => {
  assert.deepEqual(toJsonSchema(z.array(z.string())), {
    type: 'array',
    items: { type: 'string' },
  });
  assert.deepEqual(toJsonSchema(z.array(z.number()).min(1).max(3)), {
    type: 'array',
    items: { type: 'number' },
    minItems: 1,
    maxItems: 3,
  });
});

test('records publish the value schema as additionalProperties', () => {
  assert.deepEqual(toJsonSchema(z.record(z.string(), z.number())), {
    type: 'object',
    additionalProperties: { type: 'number' },
  });
});

test('wrappers are unwrapped and defaults are published', () => {
  assert.deepEqual(toJsonSchema(z.string().optional()), { type: 'string' });
  assert.deepEqual(toJsonSchema(z.string().nullable()), {
    anyOf: [{ type: 'string' }, { type: 'null' }],
  });
  assert.deepEqual(toJsonSchema(z.string().default('x')), {
    type: 'string',
    default: 'x',
  });
  assert.deepEqual(toJsonSchema(z.string().prefault('y')), {
    type: 'string',
    default: 'y',
  });
});

test('unions publish every member', () => {
  assert.deepEqual(toJsonSchema(z.union([z.string(), z.number()])), {
    anyOf: [{ type: 'string' }, { type: 'number' }],
  });
});

test('objects separate required from optional properties', () => {
  assert.deepEqual(
    toJsonSchema(z.object({ id: z.string(), note: z.string().optional() }).strict()),
    {
      type: 'object',
      properties: { id: { type: 'string' }, note: { type: 'string' } },
      required: ['id'],
      additionalProperties: false,
    },
  );
});

test('a defaulted property is not required', () => {
  assert.deepEqual(toJsonSchema(z.object({ level: z.number().default(3) }).strict()), {
    type: 'object',
    properties: { level: { type: 'number', default: 3 } },
    additionalProperties: false,
  });
});

test('an unsupported construct is refused instead of mis-published', () => {
  assert.throws(
    () => toJsonSchema(z.date()),
    /toJsonSchema does not support/,
    'a construct the walker cannot express must throw',
  );
});

test('a non-zod-4 schema is refused', () => {
  assert.throws(
    () => toJsonSchema({ _def: { typeName: 'ZodString' } } as unknown as z.ZodTypeAny),
    /requires the zod 4 schema shape/,
  );
});
